expanded AS (
    SELECT
        d.id AS discipline_id,
        v.sex,
        'adult' AS age_group,
        v.timing_type,
        v.track_length_meters,
        v.water_pit,
        v.rank_codes[rank_index] AS rank_code,
        v.marks[rank_index] AS mark_display,
        v.notes
    FROM variants v
    JOIN disciplines d ON d.code = v.discipline_code
    CROSS JOIN generate_subscripts(v.rank_codes, 1) AS rank_index
)
INSERT INTO rank_standards (
    discipline_id,
    sex,
    age_group,
    timing_type,
    track_length_meters,
    water_pit,
    rank_code,
    mark_display,
    result_seconds,
    valid_from,
    source_title,
    source_url,
    notes
)
SELECT
    discipline_id,
    sex,
    age_group,
    timing_type,
    track_length_meters,
    water_pit,
    rank_code,
    mark_display,
    parse_mark_to_seconds(mark_display),
    DATE '2024-11-26',
    'ЕВСК по легкой атлетике, действует с 26 ноября 2024 г.',
    'https://rusathletics.info/uploads/content/docs/lyubiteli/legkaya-atletika-dejstvuyut-c-26-noyabrya-2024-g-87b8cad5ee-1.pdf',
    notes
FROM expanded;
